<?php require_once __DIR__.'/../config.php';require_admin();if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$label=trim($_POST['label']??'');$amount=$_POST['amount']??'';$date=$_POST['expense_date']??date('Y-m-d');if($label&&is_numeric($amount)&&(float)$amount>=0){db()->prepare('INSERT INTO expenses(label,amount,expense_date) VALUES(?,?,?)')->execute([$label,(float)$amount,$date]);flash('Expense recorded.');}else flash('Enter a valid expense.','error');header('Location: /powervault/admin/profit-loss.php');exit;}$pdo=db();$revenue=(float)$pdo->query("SELECT COALESCE(SUM(total-discount),0) FROM orders WHERE status<>'Cancelled'")->fetchColumn();$cogs=(float)$pdo->query("SELECT COALESCE(SUM(oi.unit_price*oi.quantity),0) FROM order_items oi JOIN orders o ON o.id=oi.order_id WHERE o.status<>'Cancelled'")->fetchColumn();$cost=(float)$pdo->query("SELECT COALESCE(SUM(p.cost_price*oi.quantity),0) FROM order_items oi JOIN orders o ON o.id=oi.order_id JOIN products p ON p.id=oi.product_id WHERE o.status<>'Cancelled' AND p.cost_price IS NOT NULL")->fetchColumn();$missing=(int)$pdo->query("SELECT COUNT(DISTINCT p.id) FROM order_items oi JOIN orders o ON o.id=oi.order_id JOIN products p ON p.id=oi.product_id WHERE o.status<>'Cancelled' AND p.cost_price IS NULL")->fetchColumn();$expenses=(float)$pdo->query('SELECT COALESCE(SUM(amount),0) FROM expenses')->fetchColumn();$rows=$pdo->query('SELECT * FROM expenses ORDER BY expense_date DESC,id DESC LIMIT 30')->fetchAll();$pageTitle='Profit & Loss';require __DIR__.'/../includes/header.php';?><section class="section-pad"><div class="container-fluid admin-layout"><aside class="admin-sidebar"><div class="eyebrow">CONTROL CENTER</div><a href="/powervault/admin/">▦ Dashboard</a><a href="/powervault/admin/products.php">◇ Products</a><a href="/powervault/admin/inventory.php">▤ Inventory</a><a href="/powervault/admin/orders.php">⇄ Orders</a><a class="active" href="/powervault/admin/profit-loss.php">⌁ Profit & Loss</a><a href="/powervault/admin/settings.php">⚙ Settings</a><a href="/powervault/logout.php">↪ Logout</a></aside><div class="admin-content"><div class="eyebrow">FINANCIAL OVERVIEW</div><h1>Profit & <span class="gradient-text">Loss</span></h1><div class="stats-grid mt-4"><div class="stat-card"><span>Net Sales (excl. discount)</span><b><?=money($revenue)?></b></div><div class="stat-card"><span>Recorded Product Cost</span><b><?=money($cost)?></b><small><?=$missing?'Some order items lack cost data':'All costs recorded for orders'?></small></div><div class="stat-card"><span>Operating Expenses</span><b><?=money($expenses)?></b></div><div class="stat-card"><span><?=($missing?'Indicative Result':'Net Result')?></span><b><?=money($revenue-$cost-$expenses)?></b><small><?=$missing?'Incomplete cost data — not actual profit':'Based on recorded costs and expenses'?></small></div></div><div class="dashboard-panel mt-4"><h3>Record Expense</h3><form method="post" class="row g-3"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="col-md-5"><label class="form-label">Expense label</label><input class="form-control" name="label" required placeholder="e.g. packaging, utilities"></div><div class="col-md-3"><label class="form-label">Amount (Rs.)</label><input class="form-control" name="amount" type="number" min="0" step=".01" required></div><div class="col-md-3"><label class="form-label">Date</label><input class="form-control" name="expense_date" type="date" value="<?=date('Y-m-d')?>"></div><div class="col-md-1 d-flex align-items-end"><button class="btn btn-neon">Add</button></div></form></div><div class="dashboard-panel mt-4"><h3>Recent Expenses</h3><div class="table-responsive"><table class="table pv-table"><thead><tr><th>Expense</th><th>Amount</th><th>Date</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=e($r['label'])?></td><td><?=money($r['amount'])?></td><td><?=e($r['expense_date'])?></td></tr><?php endforeach; ?></tbody></table></div></div></div></div></section><?php require __DIR__.'/../includes/footer.php';?>
